    const saved = localStorage.getItem('siakad_session');
    if (saved) {
      try {
        const tempUser = JSON.parse(saved);
        if (!tempUser || !tempUser.role || !tempUser.username) {
          localStorage.removeItem('siakad_session');
          if (document.getElementById('appContainer')) document.getElementById('appContainer').style.display = 'none';
          if (document.getElementById('loginContainer')) document.getElementById('loginContainer').style.display = 'flex';
          return;
        }
        if (tempUser.role === 'Siswa' || tempUser.role === 'Orang Tua') {
          localStorage.removeItem('siakad_session');
          if (document.getElementById('appContainer')) document.getElementById('appContainer').style.display = 'none';
          if (document.getElementById('loginContainer')) document.getElementById('loginContainer').style.display = 'flex';
          showToast('Akses halaman untuk Siswa dan Orang Tua sedang ditutup sementara hingga ada pemberitahuan selanjutnya.', 'danger', 7000);
          return;
        }
        const processSession = () => {
          currentUser = tempUser;
          document.getElementById('loginContainer').style.display = 'none';
          document.getElementById('appContainer').style.display = 'block';
          setupUIBasedOnRole();
          
          if (currentUser.mustChangePassword) {
            openModal('modalForceChangePassword');
          } else {
            if (currentUser.role === 'Siswa' && localStorage.getItem('cbt_active_exam_id')) {
              resumeCbtExam();
            } else {
              const isKelasVII = currentUser.kelas && String(currentUser.kelas).toUpperCase().startsWith('VII');
              const isPenempatanAktif = window.appConfig && window.appConfig.enablePenempatanKelasVII === true;
              if (currentUser.role === 'Siswa' && isKelasVII && isPenempatanAktif && !currentUser.kelas_acknowledged) {
                document.getElementById('welcomeClassLabel').innerText = (currentUser.kelas || '').replace('-', ' ');
                openModal('modalWelcomeClass');
              }
              checkRouting(function(isAbsen) {
                if (!isAbsen) {
                  if (currentUser.role === 'Siswa') {
                    checkAndShowPresensiPopup();
                  } else {
                    switchView('dashboard');
                  }
                }
              });
              loadSettings();
            }
          }
        };

        if (false && tempUser.role === 'Siswa' && typeof detectIncognito !== 'undefined' && tempUser.username !== 'dummy' && tempUser.username !== 'siswa') {
          detectIncognito().then((result) => {
            if (!result.isPrivate) {
              Swal.fire({
                icon: 'error',
                title: 'Akses Ditolak',
                text: 'Demi keamanan ujian, Siswa WAJIB menggunakan Mode Penyamaran (Incognito / Private Window). Anda akan dikeluarkan dari sesi ini.',
                confirmButtonText: 'Keluar'
              }).then(() => {
                handleLogout();
              });
            } else {
              processSession();
            }
          }).catch(() => processSession());
        } else {
          processSession();
        }
      } catch(e) {
        localStorage.removeItem('siakad_session');
        if (document.getElementById('appContainer')) document.getElementById('appContainer').style.display = 'none';
        if (document.getElementById('loginContainer')) document.getElementById('loginContainer').style.display = 'flex';
      }
    } else {
      if (document.getElementById('appContainer')) document.getElementById('appContainer').style.display = 'none';
      if (document.getElementById('loginContainer')) document.getElementById('loginContainer').style.display = 'flex';
    }
  }

  
