  function readFileAsBase64(file) {
    return new Promise((resolve, reject) => {
      if (!file) {
        resolve(null);
        return;
      }
      const reader = new FileReader();
      reader.onload = () => resolve(reader.result);
      reader.onerror = error => reject(error);
      reader.readAsDataURL(file);
    });
  }

  function formatTanggalIndo(tgl) {
    if (!tgl) return '-';
    tgl = String(tgl);
    var bulanNama = ['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'];
    
    var parts;
    if (tgl.includes('-')) {
      parts = tgl.split('-');
    } else if (tgl.includes('/')) {
      parts = tgl.split('/');
    } else {
      return tgl; 
    }
    var y, m, d;
    if (parts[0].length === 4) {
      
      y = parseInt(parts[0]); m = parseInt(parts[1]); d = parseInt(parts[2]);
    } else {
      
      d = parseInt(parts[0]); m = parseInt(parts[1]); y = parseInt(parts[2]);
    }
    if (isNaN(d) || isNaN(m) || isNaN(y) || m < 1 || m > 12) return tgl;
    return d + ' ' + bulanNama[m - 1] + ' ' + y;
  }

  
