  function handleStatusOrtuChange(parent, status, prefix) {
    
    const isAdmin = currentUser && (currentUser.role === 'Admin' || currentUser.role === 'Kesiswaan' || currentUser.role === 'Operator');
    const isDeceasedOrUnknown = (status === 'Meninggal' || status === 'Tidak Diketahui');
    const pendField = document.getElementById(prefix + 'Pendidikan' + parent);
    const kerjaField = document.getElementById(prefix + 'Pekerjaan' + parent);
    
    if (isDeceasedOrUnknown) {
      pendField.value = '-';
      kerjaField.value = '-';
      pendField.disabled = true;
      kerjaField.disabled = true;
      pendField.removeAttribute('required');
      kerjaField.removeAttribute('required');
    } else {
      if (pendField.value === '-') pendField.value = '';
      if (kerjaField.value === '-') kerjaField.value = '';
      pendField.disabled = false;
      kerjaField.disabled = false;
      if (!isAdmin) pendField.setAttribute('required', 'true');
      if (!isAdmin) kerjaField.setAttribute('required', 'true');
    }
  }

