  function downloadCSVTemplate() {
    const choice = prompt(
      'Pilih format CSV untuk diunduh:\n\n' +
      '1 = Template Baru (No, NISN, NIK, Nama, Tempat Lahir, Jenis Kelamin, Asal Sekolah)\n' +
      '2 = Template Basis Login Lama (nama_siswa, nisn, tempat_lahir, tanggal_lahir, lp, asal_sekolah)\n' +
      '3 = Template Simpel (nama, nisn, jenis_kelamin)\n' +
      '4 = Template Lengkap (nis, nama, kelas, tempat_lahir, tanggal_lahir, alamat, no_hp)\n\n' +
      'Masukkan angka 1, 2, 3, atau 4:', 
      '1'
    );
    
    if (choice === null) return; 
    
    let csvContent, filename;
    if (choice === '1') {
      csvContent = 'No,NISN,NIK,Nama,Tempat Lahir,Jenis Kelamin,Asal Sekolah\n1,9988776655,3515000000000001,Andi Wijaya,Surabaya,Laki-laki,SD N 1 Surabaya\n2,9988776656,3515000000000002,Siti Aminah,Malang,Perempuan,SD N 2 Malang';
      filename = 'template_import_siswa_baru.csv';
    } else if (choice === '2') {
      csvContent = 'nama_siswa,nisn,tempat_lahir,tanggal_lahir,lp,asal_sekolah\nAndi Wijaya,9988776655,Surabaya,22-02-2012,L,SD N 1 Surabaya\nSiti Aminah,9988776656,Malang,15/08/2012,P,SD N 2 Malang';
      filename = 'template_import_siswa_login_basis.csv';
    } else if (choice === '3') {
      csvContent = 'nama,nisn,jenis_kelamin\nAhmad Fauzi,0123456789,Laki-laki\nSiti Nurhaliza,0123456790,Perempuan';
      filename = 'template_import_siswa_simpel.csv';
    } else if (choice === '4') {
      csvContent = 'nis,nama,kelas,tempat_lahir,tanggal_lahir,alamat,no_hp\n1001,Ahmad Fauzi,VII-A,Jakarta,2010-05-15,Jl. Merdeka 10,081234567890\n1002,Siti Nurhaliza,VII-B,Bandung,2010-08-20,Jl. Sudirman 5,081987654321';
      filename = 'template_import_siswa_lengkap.csv';
    } else {
      showToast('Pilihan tidak valid! Harap masukkan angka 1, 2, 3, atau 4.', 'warning');
      return;
    }
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = filename;
    link.click();
    showToast('Template CSV berhasil diunduh!', 'success');
  }

  function handleImportCSV(input) {
    const file = input.files[0];
    if (!file) return;
    if (!file.name.endsWith('.csv')) {
      showToast('File harus berformat CSV!', 'warning');
      input.value = '';
      return;
    }
    if (!confirm('Import data siswa dari file \

?\n\nSistem mendukung 4 format:\n1. Baru (No, NISN, NIK, Nama, Tempat Lahir, Jenis Kelamin, Asal Sekolah)\n2. Basis Login Lama (nama_siswa, nisn, tempat_lahir, tanggal_lahir, lp, asal_sekolah)\n3. Simpel (nama, nisn, jenis_kelamin)\n4. Lengkap (nis, nama, kelas, tempat_lahir, tanggal_lahir, alamat, no_hp)')) {
      input.value = '';
      return;
    }

    showLoading();
    const reader = new FileReader();
    reader.onload = function(e) {
      const csvContent = e.target.result;
      google.script.run
        .withSuccessHandler((response) => {
          hideLoading();
          if (response.success) {
            let msg = response.message;
            if (response.errorRows && response.errorRows.length > 0) {
              msg += '\n\nDetail Error/Skip (Max 10 baris):\n' + response.errorRows.slice(0, 10).join('\n');
              alert(msg);
            } else {
              showToast(msg, 'success');
            }
            loadSiswaData();
          } else {
            showToast('Import gagal: ' + response.message, 'danger');
          }
          input.value = '';
        })
        .withFailureHandler((err) => {
          hideLoading();
          showToast('Error: ' + err.message, 'danger');
          input.value = '';
        })
        .importSiswaFromCSV(csvContent);
    };
    reader.readAsText(file);
  }

  
