    if(existingLock) existingLock.remove();
  
    if(url) {
      input.style.display = 'none';
      const msg = document.createElement('div');
      msg.className = 'upload-locked-msg';
      msg.style.marginTop = '8px';
      
      let previewHtml = `<img src=\

>🗑️ Hapus</button>
